function icon(name, size = 20) {
  const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  svg.setAttribute("viewBox", "0 0 24 24");
  svg.setAttribute("width", size); svg.setAttribute("height", size);
  svg.setAttribute("class", "ic"); svg.setAttribute("aria-hidden", "true");
  svg.innerHTML = ICONS[name];                        // fixed markup from the table above, never user text
  return svg;
}
// Any element with data-icon gets its icon placed before its text.
function placeIcons(root = document) {
  for (const node of root.querySelectorAll("[data-icon]")) {
    if (node.querySelector(":scope > .ic")) continue;
    node.prepend(icon(node.dataset.icon, Number(node.dataset.iconSize) || 20));
  }
}
